#!/usr/bin/env python3
import argparse
import re
import sys
from pathlib import Path

ACTION_KEYWORDS = [
    r"todo",
    r"follow-up",
    r"proxima\s*acao",
    r"tarefa",
    r"pending\s*decision",
    r"next\s*action",
    r"action\s*item",
]

def parse_history(history_content):
    turns = []
    for line in history_content.strip().splitlines():
        line = line.strip()
        if not line:
            continue
        match = re.match(r"^(\w+):\s*(.*)$", line)
        if match:
            role, text = match.groups()
            turns.append((role.upper(), text.strip()))
    return turns

def extract_pending_actions(turns):
    pending = []
    pattern = re.compile("|".join(ACTION_KEYWORDS), re.IGNORECASE)
    for role, text in turns:
        if pattern.search(text):
            pending.append((role, text))
    return pending

def get_recent_turns(turns, max_turns=4):
    return turns[-max_turns:] if len(turns) >= max_turns else turns

def extract_marker(text):
    markers = re.findall(r"MARKER_[A-Z0-9_]+", text)
    return markers

def generate_summary(turns, pending_actions, recent_turns, markers, max_sentences=6):
    lines = []
    lines.append("# Context Summary")
    lines.append("")
    lines.append("## Summary")
    lines.append("")
    summary_sentences = []
    for role, text in turns:
        sentences = re.split(r"[.!?]+", text)
        for sent in sentences:
            sent = sent.strip()
            if sent and len(sent) > 5:
                summary_sentences.append(sent)
                if len(summary_sentences) >= max_sentences:
                    break
        if len(summary_sentences) >= max_sentences:
            break
    for sent in summary_sentences:
        lines.append("- " + sent)
    lines.append("")
    lines.append("## Pending Actions")
    lines.append("")
    if pending_actions:
        for role, text in pending_actions:
            lines.append("- [" + role + "] " + text)
    else:
        lines.append("- No pending actions")
    lines.append("")
    lines.append("## Recent Turns")
    lines.append("")
    for role, text in recent_turns:
        lines.append("**" + role + ":** " + text)
    lines.append("")
    if markers:
        lines.append("## Verification Markers")
        lines.append("")
        for marker in markers:
            lines.append("- " + marker)
        lines.append("")
    return "\n".join(lines)

def main():
    parser = argparse.ArgumentParser(description="Context Gatekeeper")
    parser.add_argument("--history", "-i", type=str, default=None)
    parser.add_argument("--summary", "-o", type=str, required=True)
    parser.add_argument("--max-summary-sentences", type=int, default=6)
    parser.add_argument("--max-recent-turns", type=int, default=4)
    args = parser.parse_args()

    if args.history:
        history_path = Path(args.history)
        if not history_path.exists():
            print("Error: History file not found: " + args.history, file=sys.stderr)
            sys.exit(1)
        history_content = history_path.read_text(encoding="utf-8")
    else:
        history_content = sys.stdin.read()

    turns = parse_history(history_content)
    if not turns:
        print("Warning: No valid turns found in history", file=sys.stderr)

    pending_actions = extract_pending_actions(turns)
    recent_turns = get_recent_turns(turns, args.max_recent_turns)
    all_text = "\n".join([role + ": " + text for role, text in turns])
    markers = extract_marker(all_text)

    summary = generate_summary(turns, pending_actions, recent_turns, markers, args.max_summary_sentences)

    output_path = Path(args.summary)
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(summary, encoding="utf-8")

    print("Summary written to: " + args.summary)
    print("Processed " + str(len(turns)) + " turns, found " + str(len(pending_actions)) + " pending actions")
    if markers:
        print("Preserved markers: " + ", ".join(markers))

if __name__ == "__main__":
    main()
